<template><div><MallManager mode="communityComment"/><div class="app-container" style="padding-top:0"><el-card><template #header><b>点赞记录与举报审核</b></template><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="点赞记录" name="likes"/><el-tab-pane label="举报记录" name="reports"/></el-tabs><el-table :data="rows" stripe><el-table-column prop="id" label="ID"/><el-table-column v-if="tab==='likes'" prop="postId" label="动态ID"/><el-table-column v-if="tab==='likes'" prop="nickname" label="点赞人"/><el-table-column v-if="tab==='reports'" prop="post_id" label="动态ID"/><el-table-column v-if="tab==='reports'" prop="comment_id" label="评论ID"/><el-table-column v-if="tab==='reports'" prop="reason" label="举报原因"/><el-table-column prop="status" label="状态"/><el-table-column prop="createTime" label="时间"/><el-table-column v-if="tab==='reports'" label="处理"><template #default="s"><el-button v-if="s.row.status==='待处理'" link type="success" @click="review(s.row,'已处理')">处理</el-button><el-button v-if="s.row.status==='待处理'" link type="danger" @click="review(s.row,'已驳回')">驳回</el-button></template></el-table-column></el-table></el-card></div></div></template><script setup>import { ElMessage } from 'element-plus';import request from '@/utils/request';import MallManager from '../components/MallManager.vue';const tab=ref('likes');const rows=ref([]);async function load(){rows.value=(await request({url:`/mall/admin/community/${tab.value}`,method:'get'})).data||[]}async function review(row,status){await request({url:`/mall/admin/community/reports/${row.id}`,method:'put',data:{status,adminRemark:'后台人工审核'}});ElMessage.success('处理状态已同步');load()}onMounted(load)</script>
